// LiquidTile.cpp
float LiquidTile::getHeight(int d)
{
    if (d >= 8) d = 0;
    return (d + 1) / 9.0f;
}

// LiquidTile.cpp
int LiquidTile::getRenderedDepth(LevelSource *level, int x, int y, int z)
{
    if (level->getMaterial(x, y, z) != material) return -1;
    int d = level->getData(x, y, z);
    if (d >= 8) d = 0;
    return d;
}

// LiquidTile.cpp
bool LiquidTile::isSolidFace(LevelSource *level, int x, int y, int z, int face)
{
    Material *m = level->getMaterial(x, y, z);
    if (m == this->material) return false;
	if (face == Facing::UP) return true;
    if (m == Material::ice) return false;
    
    return Tile::isSolidFace(level, x, y, z, face);
}

// LiquidTile.cpp
Vec3 *LiquidTile::getFlow(LevelSource *level, int x, int y, int z)
{
    Vec3 *flow = Vec3::newTemp(0,0,0);
    int mid = getRenderedDepth(level, x, y, z);
    for (int d = 0; d < 4; d++)
	{

        int xt = x;
        int yt = y;
        int zt = z;

        if (d == 0) xt--;
        if (d == 1) zt--;
        if (d == 2) xt++;
        if (d == 3) zt++;

        int t = getRenderedDepth(level, xt, yt, zt);
        if (t < 0)
		{
            if (!level->getMaterial(xt, yt, zt)->blocksMotion())
			{
                t = getRenderedDepth(level, xt, yt - 1, zt);
                if (t >= 0)
				{
                    int dir = t - (mid - 8);
                    flow = flow->add((xt - x) * dir, (yt - y) * dir, (zt - z) * dir);
                }
            }
        } else
		{
            if (t >= 0)
			{
                int dir = t - mid;
                flow = flow->add((xt - x) * dir, (yt - y) * dir, (zt - z) * dir);
            }
        }

    }
    if (level->getData(x, y, z) >= 8)
	{
        bool ok = false;
        if (ok || isSolidFace(level, x, y, z - 1, 2)) ok = true;
        if (ok || isSolidFace(level, x, y, z + 1, 3)) ok = true;
        if (ok || isSolidFace(level, x - 1, y, z, 4)) ok = true;
        if (ok || isSolidFace(level, x + 1, y, z, 5)) ok = true;
        if (ok || isSolidFace(level, x, y + 1, z - 1, 2)) ok = true;
        if (ok || isSolidFace(level, x, y + 1, z + 1, 3)) ok = true;
        if (ok || isSolidFace(level, x - 1, y + 1, z, 4)) ok = true;
        if (ok || isSolidFace(level, x + 1, y + 1, z, 5)) ok = true;
        if (ok) flow = flow->normalize()->add(0, -6, 0);
    }
    flow = flow->normalize();
    return flow;
}

// LiquidTile.cpp
void LiquidTile::handleEntityInside(Level *level, int x, int y, int z, shared_ptr<Entity> e, Vec3 *current)
{
    Vec3 *flow = getFlow(level, x, y, z);
    current->x += flow->x;
    current->y += flow->y;
    current->z += flow->z;
}

// Dimension.cpp
void Dimension::updateLightRamp()
{
    float ambientLight = 0.00f;
    for (int i = 0; i <= Level::MAX_BRIGHTNESS; i++)
	{
        float v = (1 - i / (float) (Level::MAX_BRIGHTNESS));
        brightnessRamp[i] = ((1 - v) / (v * 3 + 1)) * (1 - ambientLight) + ambientLight;
    }
}

// Entity.cpp
void Entity::_init(bool useSmallId)
{
	// 4J - changed to assign two different types of ids. A range from 0-2047 is used for things that we'll be wanting to identify over the network,
	// so we should only need 11 bits rather than 32 to uniquely identify them. The rest of the range is used for anything we don't need to track like this,
	// currently particles. We only ever want to allocate this type of id from the server thread, so using thread local storage to isolate this.
	if( useSmallId && ((size_t)TlsGetValue(tlsIdx) != 0 ) )
	{
		entityId = getSmallId();
	}
	else
	{
		entityId = Entity::entityCounter++;
		if(entityCounter == 0x7ffffff ) entityCounter = 2048;
	}

	viewScale = 1.0;

	blocksBuilding = false;
	rider = weak_ptr<Entity>();
	riding = nullptr;

	//level = NULL; // Level is assigned to in the original c_tor code
	xo = yo = zo = 0.0;
	x = y = z = 0.0;
	xd = yd = zd = 0.0;
	yRot = xRot = 0.0f;
	yRotO = xRotO = 0.0f;
	bb = AABB::newPermanent(0, 0, 0, 0, 0, 0); // 4J Was final
	onGround = false;
	horizontalCollision = verticalCollision = false;
	collision = false;
	hurtMarked = false;
	isStuckInWeb = false;

	slide = true;
	removed = false;
	heightOffset = 0 / 16.0f;

	bbWidth = 0.6f;
	bbHeight = 1.8f;

	walkDistO = 0;
	walkDist = 0;

	fallDistance = 0;

	nextStep = 1;

	xOld = yOld = zOld = 0.0;
	ySlideOffset = 0;
	footSize = 0.0f;
	noPhysics = false;
	pushthrough = 0.0f;

	random = new Random();

	tickCount = 0;
	flameTime = 1;

	onFire = 0;
	wasInWater = false;


	invulnerableTime = 0;

	firstTick = true;


	customTextureUrl = L"";
	customTextureUrl2 = L"";


	fireImmune = false;

	// values that need to be sent to clients in SMP
	entityData = shared_ptr<SynchedEntityData>(new SynchedEntityData());

	xRideRotA = yRideRotA = 0.0;
	inChunk = false;
	xChunk = yChunk = zChunk = 0;
	xp = yp = zp = 0;
	xRotp = yRotp = 0;
	noCulling = false;

	hasImpulse = false;

	// 4J Added
	m_ignoreVerticalCollisions = false;
	m_uiAnimOverrideBitmask = 0L;
}

// Entity.cpp
Entity::Entity(Level *level, bool useSmallId)	// 4J - added useSmallId parameter
{
	MemSect(16);
	_init(useSmallId);
	MemSect(0);

	this->level = level;
	// resetPos();
	setPos(0, 0, 0);

	entityData->define(DATA_SHARED_FLAGS_ID, (byte) 0);
	entityData->define(DATA_AIR_SUPPLY_ID, TOTAL_AIR_SUPPLY); // 4J Stu - Brought forward from 1.2.3 to fix 38654 - Gameplay: Player will take damage when air bubbles are present if resuming game from load/autosave underwater.

	// 4J Stu - We cannot call virtual functions in ctors, as at this point the object
	// is of type Entity and not a derived class
	//this->defineSynchedData();
}

