// Entity.cpp
void Entity::resetPos()
{
	if (level == NULL) return;

	shared_ptr<Entity> sharedThis = shared_from_this();
	while (true && y > 0)
	{
		setPos(x, y, z);
		if (level->getCubes(sharedThis, bb)->empty()) break;
		y += 1;
	}

	xd = yd = zd = 0;
	xRot = 0;
}

